import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { retryJobHandler } from "../handlers/retryJobHandler";
import type { ApiError } from "../runtime/client";
import type { FeedPartition } from "../types/FeedPartition";
import type { SocialPlatform } from "../types/SocialPlatform";

type Data = Awaited<ReturnType<typeof retryJobHandler>>;
type Vars = { postId: FeedPartition; platform: SocialPlatform };

export function useRetryJob(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => retryJobHandler(vars.postId, vars.platform),
    ...options,
  });
}
